function padAudit(n: number): AuditEvent[] {
  const actions = [
    "login",
    "logout",
    "login_failed",
    "settlement_created",
    "settlement_submitted",
    "settlement_approved",
    "settlement_rejected",
    "settlement_closed",
    "settlement_reversed",
    "report_exported",
    "agent_assignment_attempt_rejected",
    "permission_denied",
  ] as const;
  const events: AuditEvent[] = [];
  for (let i = 1; i <= n; i += 1) {
    const action = actions[(i - 1) % actions.length];
    events.push({
      auditId: `AUDIT-SEED-${String(i).padStart(3, "0")}`,
      actorUserId: i % 7 === 0 ? "anonymous" : "user_super",
      actorRole: i % 7 === 0 ? "anonymous" : "super_admin",
      action,
      resourceType: action.startsWith("settlement")
        ? "settlement"
        : action.startsWith("report")
          ? "report"
          : action.startsWith("agent")
            ? "agent"
            : "session",
      resourceId: action.startsWith("settlement") ? "SET-SA-001" : null,
      beforeSnapshot: action.includes("approved") ? { status: "under_review" } : undefined,
      afterSnapshot: action.includes("approved") ? { status: "approved" } : undefined,
      reason: action.includes("denied") || action.includes("rejected") || action.includes("failed")
        ? "synthetic_reason"
        : undefined,
      environment: "development",
      createdAtUtc: `2026-09-${String((i % 10) + 1).padStart(2, "0")}T${String(i % 24).padStart(2, "0")}:00:00.000Z`,
      correlationId: `corr_seed_audit_${String(i).padStart(3, "0")}`,
    });
  }
  return events;
}

export const seedAuditEvents: AuditEvent[] = padAudit(120);

